package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.repositories.*;import com.citacloud.springboot.contacloud.app.security.TenantPrincipal;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.test.util.ReflectionTestUtils;import java.math.BigDecimal;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class VentaGuardadaServiceTest {
 private final VentaGuardadaRepository ventas=mock(VentaGuardadaRepository.class);private final LineaVentaGuardadaRepository lineas=mock(LineaVentaGuardadaRepository.class);private final TerminalPosRepository terminales=mock(TerminalPosRepository.class);private final CashRegisterRepository cajas=mock(CashRegisterRepository.class);private final SucursalRepository sucursales=mock(SucursalRepository.class);private final PosWarehouseResolver almacenes=mock(PosWarehouseResolver.class);private final ProductRepository productos=mock(ProductRepository.class);private final ClienteRepository clientes=mock(ClienteRepository.class);private final InventoryMovementRepository existencias=mock(InventoryMovementRepository.class);private final AuditoriaService auditoria=mock(AuditoriaService.class);private final DescuentoVentaService descuentos=mock(DescuentoVentaService.class);private final RecargoVentaService recargos=mock(RecargoVentaService.class);private final JdbcTemplate jdbc=mock(JdbcTemplate.class);private final VentaGuardadaService service=new VentaGuardadaService(ventas,lineas,terminales,cajas,sucursales,almacenes,productos,clientes,existencias,auditoria,descuentos,recargos,jdbc);
 private final UUID tenant=UUID.randomUUID(),empresa=UUID.randomUUID(),usuario=UUID.randomUUID(),sucursalId=UUID.randomUUID(),cajaId=UUID.randomUUID(),terminalId=UUID.randomUUID(),almacenId=UUID.randomUUID(),monedaId=UUID.randomUUID(),productoId=UUID.randomUUID();
 @BeforeEach void setup(){TenantPrincipal p=new TenantPrincipal(usuario,tenant,empresa,null,"DEMO","Admin","admin","",true,true,Set.of(),Set.of("ventas_guardadas.guardar"));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(p,null,p.getAuthorities()));TerminalPos terminal=mock(TerminalPos.class);when(terminal.getId()).thenReturn(terminalId);when(terminal.getCajaId()).thenReturn(cajaId);when(terminal.getSucursalId()).thenReturn(sucursalId);when(terminales.findByTokenHashAndTenantIdAndEmpresaIdAndActivoTrue(anyString(),eq(tenant),eq(empresa))).thenReturn(Optional.of(terminal));Caja caja=mock(Caja.class);Moneda moneda=mock(Moneda.class);when(moneda.getCodigoIso()).thenReturn("DOP");when(caja.getId()).thenReturn(cajaId);when(caja.getSucursalId()).thenReturn(sucursalId);when(caja.getMonedaId()).thenReturn(monedaId);when(caja.getMoneda()).thenReturn(moneda);when(caja.isActivo()).thenReturn(true);when(cajas.findByIdAndTenantIdAndEmpresaId(cajaId,tenant,empresa)).thenReturn(Optional.of(caja));Sucursal sucursal=mock(Sucursal.class);when(sucursales.findByIdAndEmpresaId(sucursalId,empresa)).thenReturn(Optional.of(sucursal));Almacen almacen=mock(Almacen.class);when(almacen.getId()).thenReturn(almacenId);when(almacenes.resolver(tenant,empresa,sucursal)).thenReturn(almacen);Producto producto=mock(Producto.class);UnidadMedida unidad=mock(UnidadMedida.class);when(unidad.getAbreviatura()).thenReturn("und");when(producto.getId()).thenReturn(productoId);when(producto.getCodigo()).thenReturn("PRD-1");when(producto.getNombre()).thenReturn("Producto");when(producto.getUnidadMedida()).thenReturn(unidad);when(producto.getMonedaId()).thenReturn(monedaId);when(producto.getPrecioVenta()).thenReturn(new BigDecimal("100.0000"));when(producto.isActivo()).thenReturn(true);when(productos.findByIdAndTenantIdAndEmpresaId(productoId,tenant,empresa)).thenReturn(Optional.of(producto));when(ventas.saveAndFlush(any())).thenAnswer(i->{VentaGuardada v=i.getArgument(0);if(v.getId()==null)ReflectionTestUtils.setField(v,"id",UUID.randomUUID());return v;});when(lineas.save(any())).thenAnswer(i->i.getArgument(0));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void impideGuardarCarritoVacioSinPersistir(){assertThatThrownBy(()->service.guardar(new GuardarVentaInput(null,"token",almacenId,null,null,null,null,null,List.of()))).hasMessage("No hay una venta para guardar.");verifyNoInteractions(ventas,jdbc);}
 @Test void guardaMultiplesVentasSinSobrescribirYConReferenciaOpcional(){when(jdbc.queryForObject(anyString(),eq(Long.class),eq(tenant),eq(empresa))).thenReturn(1L,2L);GuardarVentaInput input=new GuardarVentaInput(null,"token",almacenId,null,null,null,BigDecimal.ZERO,BigDecimal.ZERO,List.of(new LineaVentaGuardadaInput(productoId,BigDecimal.ONE,new BigDecimal("100"),BigDecimal.ZERO)));var primera=service.guardar(input);var segunda=service.guardar(input);assertThat(primera.numero()).isEqualTo("VGU-000001");assertThat(segunda.numero()).isEqualTo("VGU-000002");assertThat(primera.id()).isNotEqualTo(segunda.id());verify(ventas,times(2)).saveAndFlush(any());verify(lineas,times(2)).save(any());verifyNoInteractions(existencias);}
 @Test void limpiarUnaVentaRecuperadaLiberaElBloqueoSinDescartarla(){UUID id=UUID.randomUUID();VentaGuardada venta=new VentaGuardada(tenant,empresa,"VGU-000025",sucursalId,cajaId,terminalId,almacenId,usuario);venta.actualizar(sucursalId,cajaId,terminalId,almacenId,null,"Consumidor Final",null,monedaId,"DOP",null,null,new BigDecimal("100"),BigDecimal.ZERO,BigDecimal.ZERO,new BigDecimal("18"),new BigDecimal("118"),1,usuario);ReflectionTestUtils.setField(venta,"id",id);venta.recuperar(usuario,terminalId);when(ventas.bloquear(id,tenant,empresa)).thenReturn(Optional.of(venta));service.liberarRecuperacion(id,"token",almacenId);assertThat(venta.getEstado()).isEqualTo(EstadoVentaGuardada.SAVED);assertThat(venta.getRecuperadaPor()).isNull();verify(ventas).saveAndFlush(venta);verifyNoInteractions(lineas,existencias);}
 @Test void noLiberaUnaVentaDeOtroTenant(){UUID id=UUID.randomUUID();when(ventas.bloquear(id,tenant,empresa)).thenReturn(Optional.empty());assertThatThrownBy(()->service.liberarRecuperacion(id,"token",almacenId)).isInstanceOf(RecursoNoEncontradoException.class);verify(ventas,never()).saveAndFlush(any());}
 @Test void listadoEmergenteSolicitaCincoRegistrosAlBackend(){when(ventas.buscar(eq(tenant),eq(empresa),eq(sucursalId),eq(usuario),eq(terminalId),eq(false),eq("venta"),any())).thenReturn(org.springframework.data.domain.Page.empty(org.springframework.data.domain.PageRequest.of(0,5)));service.buscar("token"," VENTA ",0);verify(ventas).buscar(eq(tenant),eq(empresa),eq(sucursalId),eq(usuario),eq(terminalId),eq(false),eq("venta"),argThat(p->p.getPageNumber()==0&&p.getPageSize()==5));}
}
